const button=(label,action,style='',attrs='')=>`<button class="btn ${style}" data-action="${action}" ${attrs}>${label}</button>`;
const statusTag=s=>`<span class="tag ${['pending','To order'].includes(s)?'warning':['rejected','Out of stock'].includes(s)?'danger':s==='Uncounted'?'neutral':''}">${esc(s.charAt(0).toUpperCase()+s.slice(1))}</span>`;
function toast(message){const t=$('#toast');t.textContent=message;t.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.hidden=true,5000);}
function shell(content) {
  const titles={stock:'Stock overview',history:'Trends & history',requests:'Order requests'};
  $('#app').innerHTML=`<aside class="sidebar"><a class="brand" href="#stock"><span class="brand-mark">QP.</span><span class="brand-text"><strong>Stock Room</strong><span>QLUBBMÄSTERIET</span></span></a><nav aria-label="Main navigation">${Object.entries(titles).map(([id,label])=>`<a class="nav-item ${route===id?'active':''}" href="#${id}" ${route===id?'aria-current="page"':''}>${icon(id)}${label}</a>`).join('')}</nav><div class="sidebar-foot"><p class="eyebrow">One place for the pub</p><small>Plan. Stock. Serve.</small><div class="profile"><span class="avatar">${admin()?'BM':'QP'}</span><div><small>${admin()?'Barmaster':'Organization member'}</small><br><span class="role-badge">${api.preview?'Local preview':'Private workspace'}</span></div></div>${api.preview?'':`<button data-action="signout" class="signout">Sign out</button>`}</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb"><span>QP workspace</span><span class="slash">/</span><span>${titles[route]}</span></div><div class="private-label">${icon('lock')}Organization only${!api.preview?'<button data-action="signout" class="link-button">Sign out</button>':''}</div></header>${api.preview?'<div class="preview-band"><strong>LOCAL PREVIEW</strong><span>Sample stock & events · real imported sales · changes are temporary and never sent.</span></div>':''}<main id="main" class="main" tabindex="-1">${content}</main></div>`;
}
function deliveryPlanSection(){
 const plans=datedPlan(CATALOG,data,new Date(),deliveryChoice),active=plans.filter(p=>p.needs.length||p.unknown),deliveries=plans.flatMap(p=>p.deliveries.map(d=>({...d,product:p.product}))).sort((a,b)=>a.date.localeCompare(b.date));
 return `<section class="panel history-table"><div class="panel-head"><div><h2>Pub & event stock plan</h2><p>Next 8 weeks · approved reservations plus normal pub usage</p></div></div><div class="panel-body">${!data.planningAvailable?'<p class="notice info">Run planning.sql to enable separate pub/event opening types. Existing openings retain their previous estimates until reviewed.</p>':''}<label for="delivery-choice">Martin &amp; Servera delivery preference · this preview</label><select id="delivery-choice" class="control">${[['latest','Latest suitable Tuesday or Thursday'],['tuesday','Tuesdays only'],['thursday','Thursdays only']].map(([v,n])=>`<option value="${v}" ${deliveryChoice===v?'selected':''}>${n}</option>`).join('')}</select><p class="small muted">Spendrups: Tuesday. Both suppliers: order by the preceding Sunday, 23:59 Stockholm time. Dates are suggestions, not booked deliveries. Same-day arrival times need confirmation; tap beer also needs 48 hours of chilling.</p><details class="disclosure" open><summary>Suggested deliveries · ${deliveries.length} product lines</summary><div>${deliveries.map(d=>`<article class="inventory-product"><div><strong>${dateLabel(d.date)} · ${esc(d.product.supplier)}</strong><p>${esc(d.product.name)}: ${fmt(d.packs)} packs (${fmt(d.quantity,2)} ${esc(d.product.unit)}) · for ${esc(d.event_name)}</p><small>Order by ${dateLabel(d.cutoff,{hour:'2-digit',minute:'2-digit'})}${d.arrivalNeedsConfirmation?' · Confirm arrival before '+dateLabel(d.readyBy,{hour:'2-digit',minute:'2-digit'}):''}</small>${d.excess?`<p class="notice">${fmt(d.excess,2)} ${esc(d.product.unit)} above comfortable capacity after arrival. ${d.product.id==='tap'?'Keg slots are a physical limit; arrange capacity or an alternative supply.':'Arrange temporary storage before ordering.'}</p>`:''}${d.product.id==='tap'?'<p class="small muted">Check occupied keg slots and fridge availability; volume alone does not prove the kegs will fit or chill in time.</p>':''}</div></article>`).join('')||'<p>No feasible extra delivery lines yet. Check counts, scheduled openings and warnings below.</p>'}</div></details><details class="disclosure"><summary>What to protect for pubs and events</summary><div class="purchase-scroll"><table class="stock-table reservation-table"><thead><tr><th>Product</th><th>On hand</th><th>Pub needs</th><th>Event reservations</th><th>Reserve</th></tr></thead><tbody>${active.map(p=>`<tr><td>${esc(p.product.name)} ${p.unknown?'· count needed':''}</td><td>${fmt(p.stock,2)}</td><td>${fmt(p.pubHold,2)}</td><td>${fmt(p.eventHold,2)}</td><td>${fmt(p.reserve,2)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Quantities are in each product’s stock unit. These are needs across the planning period; later deliveries can supply later events. Pending requests are not committed reservations.</p></details>${plans.flatMap(p=>p.needs.filter(n=>n.missedCutoff).map(n=>`<p class="notice error">${esc(p.product.name)} · ${esc(n.name)}: no orderable delivery before it is needed. ${fmt(n.uncovered,2)} ${esc(p.product.unit)} uncovered; ${fmt(n.packs)} packs needed to meet demand and reserve. Contact the supplier or change the plan.</p>`)).join('')}<details class="disclosure"><summary>Estimate normal pub usage from history</summary><p>Mark past normal openings as “Normal pub”, and map a product’s exact till label in the stock editor. Rates below use QP sales on those calendar dates, including zero-sale dates within imported coverage. Overnight sales and mixed-event days need review. Generic cider or soda buttons must not be assigned to multiple flavours.</p>${CATALOG.map(p=>{const t=trendRate(p,data);return t?`<p><strong>${esc(p.name)}</strong>: ${fmt(t.rate,2)} ${esc(p.unit)} per reference date (${t.dates} dates); current planning rate ${fmt(p.rate,2)}. Review and enter the rate in the stock editor.</p>`:''}).join('')||'<p>No mapped products with reference pub dates yet. Existing planning rates remain in use.</p>'}</details></div></section>`;
}
function requestImpact(r,eventId){
 const event=data.events.find(e=>e.id===eventId);if(!event)return 'Choose the scheduled opening to preview stock and deliveries.';
 const scenario={...data,approvedDemand:[...(data.approvedDemand||[]),{...r,status:'approved',event_id:eventId}]},plans=datedPlan(CATALOG.filter(p=>r.lines.some(l=>l.product_id===p.id)),scenario,new Date(),deliveryChoice);
 return `<p>Preview if approved. ${event.kind==='pub'?'These quantities are added to normal pub needs.':event.kind==='event'?'This event uses approved request quantities.':'This older opening uses the larger of its estimate and requests. Edit its opening type to make the split explicit.'}</p>${plans.map(p=>`<p><strong>${esc(p.product.name)}</strong>: ${p.unknown?'stock count needed':`${fmt(p.pubHold,2)} for pubs + ${fmt(p.eventHold,2)} reserved for events; ${p.deliveries.map(d=>fmt(d.packs)+' packs on '+dateLabel(d.date)).join(', ')||'no feasible additional delivery proposed'}${p.needs.some(n=>n.missedCutoff)?' · delivery cutoff missed':''}${p.temporaryExcess?' · temporary storage required':''}`}</p>`).join('')}`;
}
function stockPage(){
  const forecast=forecasts(data),now=new Date();
  const upcoming=data.events.filter(e=>!e.cancelled&&new Date(e.starts_at)>now).sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at));
  const ordered=forecast.filter(p=>p.packs>0),unknown=forecast.filter(p=>p.quantity===null),short=forecast.filter(p=>p.blocked);
  const next=upcoming[0],selected=filter==='All products'?forecast:filter==='To order'?forecast.filter(p=>p.wanted>0):forecast.filter(p=>p.group===filter);
  const supplierNames=[...new Set(ordered.map(p=>p.supplier))];
  shell(`<div class="page-heading"><div><p class="eyebrow">The stock room</p><h1>Ready for the next round.</h1><p>What’s on hand, how long it lasts, and what comes next.</p></div></div>
  ${admin()?`<section class="task-grid" aria-label="Stock tasks"><button data-action="inventory"><span class="task-icon">＋</span><strong>Count stock</strong><small>Pick a few products. Count as you go.</small></button><button data-action="delivery"><span class="task-icon">↓</span><strong>Receive delivery</strong><small>Check what arrived against your order.</small></button><button data-action="supplier-order"><span class="task-icon">↗</span><strong>Record an order</strong><small>Prepare the list for delivery day.</small></button></section>`:''}
  ${unknown.length?`<div class="notice info"><strong>${unknown.length} products haven’t been counted yet.</strong> Start with the ones you use. Their forecasts appear after counting.</div>`:''}
  <section class="summary-strip" aria-label="Stock summary"><div class="summary"><p class="summary-label">${icon('calendar')}Next opening</p><p class="summary-value">${next?dateLabel(next.starts_at):'Not scheduled'}</p><p class="summary-note">${next?esc(next.name)+' · '+fmt(next.multiplier,1)+'× normal usage':'Add upcoming openings to plan demand'}</p></div><div class="summary"><p class="summary-label">${icon('stock')}Products to order</p><p class="summary-value">${unknown.length===forecast.length?'—':ordered.length}<span class="unit"> / ${forecast.length} products</span></p><p class="summary-note">${upcoming.length?`Planning for the next ${Math.min(2,upcoming.length)} opening${upcoming.length>1?'s':''}`:'Minimum levels only · schedule missing'}</p></div><div class="summary"><p class="summary-label">${icon('requests')}Event requests</p><p class="summary-value">${data.requests.filter(r=>r.status==='pending').length}<span class="unit"> pending</span></p><p class="summary-note">${admin()?'Waiting for your review':'Your requests awaiting review'}</p></div></section>
  <div class="stock-layout"><section class="panel"><div class="panel-head"><div><h2>On the shelves</h2><p>${api.preview?'Illustrative stock counts':'Estimates from counts, deliveries and scheduled use'}</p></div><span class="muted small">${forecast.length} products</span></div><div class="filter-row" role="group" aria-label="Filter stock">${['Choose a category','All products','To order',...(!['Choose a category','All products','To order'].includes(filter)?[filter]:[])].map(f=>`<button class="chip ${f===filter?'active':''}" data-filter="${esc(f)}" aria-pressed="${f===filter}">${esc(f)}</button>`).join('')}</div>${filter==='Choose a category'?`<div class="library-categories stock-categories">${[...new Set(CATALOG.map(p=>p.group))].map(g=>`<button data-filter="${esc(g)}"><strong>${esc(g)}</strong><span>${forecast.filter(p=>p.group===g).length} products · ${forecast.filter(p=>p.group===g&&p.quantity!==null).length} counted ›</span></button>`).join('')}</div>`:''}<table class="stock-table" ${filter==='Choose a category'?'hidden':''}><thead><tr><th scope="col">Product</th><th scope="col">On hand</th><th scope="col">Expected to last</th></tr></thead><tbody>${selected.map(p=>`<tr><td><div class="product-name">${esc(p.name)}</div><div class="product-meta">${p.quantity===null?'Count needed':p.status==='Covered'?esc(p.group):statusTag(p.status)}</div></td><td><span class="stock-number">${fmt(p.quantity,1)}</span><span class="stock-unit">${esc(p.unit)}${p.countMode==='bottle'?' · '+fmt(p.quantity==null?null:p.quantity*p.sizeMl)+' ml (estimate)':''}</span></td><td><span class="cover-number">${p.quantity===null?'—':p.coverage===null?'No usage estimate':fmt(p.coverage,1)+' openings'}</span>${p.coverage!==null?`<div class="meter ${p.coverage<2?'warning':''}"><i style="width:${Math.min(100,p.coverage/4*100)}%"></i></div><div class="product-meta" style="margin-top:6px">${p.runout?'Short on '+dateLabel(p.runout):'At normal usage'}</div>`:''}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Choose a category above to see its stock.</td></tr>'}</tbody></table><div class="footnote" ${filter==='Choose a category'?'hidden':''}>“Openings” assumes a normal pub night. Dated shortages include event multipliers and approved requests.</div></section>
  <aside class="stock-aside"><section class="order-panel"><p class="eyebrow">Next delivery</p><h2>To order</h2>${admin()&&(data.supplierOrders||[]).some(o=>o.status==='ordered')?`<p class="sub">${data.supplierOrders.filter(o=>o.status==='ordered').length} orders await delivery. These suggestions use on-hand stock; check saved orders before ordering again.</p>${button('View expected deliveries','delivery','quiet')}`:''}<p class="sub">${next?'Ready before '+dateLabel(next.starts_at):'Set an opening date to plan delivery'} · ${unknown.length?'counts incomplete':'whole packs only'}</p><div class="order-total">${unknown.length===forecast.length?'—':ordered.reduce((s,p)=>s+p.packs,0)}<span>packs suggested</span></div><p class="sub">${upcoming.length?'Covers the next '+Math.min(2,upcoming.length)+' openings + reserve':'Reserve levels only'}</p>${supplierNames.map(s=>`<div class="supplier"><h3>${esc(s)}</h3>${ordered.filter(p=>p.supplier===s).map(p=>`<div class="order-line"><div>${esc(p.name)}<small>${fmt(p.packs*p.pack)} ${esc(p.unit)} · ${fmt(p.pack)} per ${p.id==='tap'?'keg':'pack'}${p.packAssumed?' · verify pack':''}</small></div><strong>× ${fmt(p.packs)}</strong></div>`).join('')}</div>`).join('')||'<div class="supplier"><p class="sub">'+(unknown.length?'Add stock counts to calculate quantities.':'No additional packs needed for this horizon.')+'</p></div>'}${short.length?`<p class="capacity-warning">${short.length} product${short.length>1?'s':''} cannot reach the target within storage capacity. ${short.map(p=>esc(p.name)).join(', ')}.</p>`:''}${ordered.length?button(icon('copy')+' Copy order list','copy-order','lime'):''}</section><section class="note-card"><h3>${icon('time')}Give the kegs 48 hours.</h3><p>${next?'Move warm kegs into the fridge by '+dateLabel(new Date(new Date(next.starts_at)-48*3600000).toISOString(),{hour:'2-digit',minute:'2-digit'})+'.':'Set the next opening to calculate the chilling deadline.'} Three chilled slots. Four warm slots.</p>${button('View keg readiness','kegs','quiet')}</section></aside></div>
  <div class="bottom-note"><p>${api.preview?'Sample stock counted today':data.counts.length?'Latest count: '+dateLabel(data.counts.map(c=>c.counted_at).sort().at(-1)):'No stock counts yet'} · ${api.preview?'Not shared':'Shared across the organization'}</p><div class="buttons">${admin()?button('Opening schedule','schedule','quiet')+button('Product library','product-library','quiet')+button('Stock adjustments','manage-stock','quiet')+button('Planning assumptions','settings','quiet'):button('Planning assumptions','assumptions','quiet')}</div></div><details class="disclosure"><summary>Pub reservations & delivery planning</summary>${deliveryPlanSection()}</details>`);
}
function purchaseHistory(){
  const orders=(data.purchases||[]).filter(o=>o.date>=range.from&&o.date<=range.to).sort((a,b)=>b.date.localeCompare(a.date));
  const total=orders.reduce((sum,o)=>sum+Number(o.net_ore),0);
  const sourceLink=o=>/^https:\/\/drive\.google\.com\/file\/d\/[A-Za-z0-9_-]+\/view(?:\?.*)?$/.test(o.source_url)?`<a href="${esc(o.source_url)}" target="_blank" rel="noopener noreferrer">Open invoice</a>`:'';
  return `<section class="panel history-table"><div class="panel-head"><div><h2>Purchase history</h2><p>QP orders · Spendrups and Martin &amp; Servera</p></div><span class="tag neutral">${orders.length} delivery / return records</span></div><div class="panel-body"><p><strong>${fmt(total/100,2)} SEK</strong> excluding VAT, including invoiced deposits, returns and fees.</p><p class="small muted">Uses the dates above; sales-category filters do not apply. Only identified QP orders are included. Missing or uncertain order references are held for review. Imported invoices do not update stock.</p>${data.purchasesAvailable===false?'<div class="notice info">Purchase history has not been set up in the database yet.</div>':!orders.length?'<div class="empty">No imported QP purchases in this date range.</div>':''}${orders.map(o=>`<details class="disclosure"><summary>${dateLabel(o.date,{year:'numeric'})} · ${esc(o.supplier)} · ${esc(o.order_reference)} · ${fmt(Number(o.net_ore)/100,2)} SEK</summary><div><p>Invoice ${esc(o.invoice_number)} · Supplier order ${esc(o.supplier_order)}${o.delivery_number?' · Delivery '+esc(o.delivery_number):''} · ${sourceLink(o)}</p><div class="purchase-scroll"><table class="stock-table purchase-items"><thead><tr><th>Product / charge</th><th>Quantity</th><th>Pack size</th><th>Net · SEK</th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(l.description)}<small class="muted"> ${esc(l.sku)} · ${esc(l.kind)}</small></td><td>${l.quantity===null?'—':fmt(l.quantity,2)} ${esc(l.unit||'')}</td><td>${l.pack_size||'Not specified'}</td><td>${fmt(l.net_ore/100,2)}</td></tr>`).join('')}</tbody></table></div><p class="small muted">Quantities use the invoice unit: KLI/KRT = packs, ST = pieces, PAL/BACK = pallets/crates. Unknown pack sizes are not converted. Martin &amp; Servera product prices may include deposits.</p></div></details>`).join('')}</div></section>`;
}
function historyPage(){
  pubYear??=pubYears(data)[0]||Number(today().slice(0,4));
  const stats=aggregateSales(data.sales,range.from,range.to,range.category),meta=data.imports[0],namedProducts=popularNamedProducts(stats.products,CATALOG);
  const months={};
  if(range.from<=range.to) {let d=new Date(range.from.slice(0,7)+'-01T12:00:00Z');const end=new Date(range.to+'T12:00:00Z');while(d<=end&&Object.keys(months).length<60){months[d.toISOString().slice(0,7)]=0;d.setUTCMonth(d.getUTCMonth()+1);}}
  for(const r of stats.daily)months[r.date.slice(0,7)]=(months[r.date.slice(0,7)]||0)+r.revenue;
  const entries=Object.entries(months),max=Math.max(1,...entries.map(e=>Math.abs(e[1])/100));
  const chartWidth=620,step=entries.length?540/entries.length:1;
  const coverageStart=data.imports.length?data.imports.map(m=>m.range_start).sort()[0]:null,coverageEnd=data.imports.length?data.imports.map(m=>m.range_end).sort().at(-1):null;
  const chart=`<svg class="chart" viewBox="0 0 620 255" role="img" aria-label="Monthly sales revenue after refunds. Exact values are available in the table below.">${[0,1,2,3].map(i=>{const y=200-i*55;return `<line x1="55" y1="${y}" x2="605" y2="${y}" stroke="#e8eeeb"/><text x="47" y="${y+4}" text-anchor="end">${fmt(max*i/3/1000,0)}k</text>`;}).join('')}${entries.map(([m,value],i)=>{const h=Math.abs(value/100)/max*165,x=62+i*step;return `<rect class="bar" x="${x}" y="${value>=0?200-h:200}" width="${Math.max(2,step*.52)}" height="${h}" rx="3"><title>${m}: ${fmt(value/100,2)} SEK</title></rect><text x="${x+step*.26}" y="230" text-anchor="middle">${dateLabel(m+'-01',{month:'short',day:undefined})}</text>`;}).join('')}</svg>`;
  shell(`<div class="page-heading"><div><p class="eyebrow">A little perspective</p><h1>Trends & history</h1><p>QP sales, with the other chapter kept separate.</p></div><span class="tag neutral">CSV history · no live feed</span></div>
  ${!data.sales.length?'<div class="notice info">No sales history has been imported into the shared database yet.</div>':''}
  <form id="history-filter" class="history-controls"><div class="field"><label for="from">From</label><input id="from" name="from" type="date" required value="${range.from}" min="2020-01-01" max="${today()}"></div><div class="field"><label for="to">To</label><input id="to" name="to" type="date" required value="${range.to}" min="2020-01-01" max="${today()}"></div><div class="field"><label for="category">Category</label><select id="category" name="category">${['all','QP','QP-NPR','QP-VPR','QP-Pitbull','QP-Plåt'].map(c=>`<option value="${c}" ${range.category===c?'selected':''}>${c==='all'?'All QP categories':c}</option>`).join('')}</select></div><button class="btn primary" type="submit">Apply dates</button><button class="btn" type="button" data-action="history-past-month">Past 30 days</button></form>
  ${coverageStart&&(range.from<coverageStart||range.to>coverageEnd)?`<div class="notice">Imported coverage is ${dateLabel(coverageStart)}–${dateLabel(coverageEnd)}. Dates outside it have no data.</div>`:''}
  ${pubInsights(data,range,pubPurchasesPerCustomer)}
  ${pubYearSection(data,pubYear,pubYearMetric,pubYearBasis)}
  <section class="summary-strip" aria-label="Sales summary"><div class="summary"><p class="summary-label">Sales after refunds</p><p class="summary-value">${fmt(stats.revenue/100)} <span class="unit">SEK</span></p><p class="summary-note">Gross revenue including tickets & food</p></div><div class="summary"><p class="summary-label">Net units sold</p><p class="summary-value">${fmt(stats.quantity)}</p><p class="summary-note">All selected products · not drink servings</p></div><div class="summary"><p class="summary-label">Dates with sales</p><p class="summary-value">${stats.daily.length}</p><p class="summary-note">Calendar dates · not opening nights</p></div></section>
  <div class="history-grid"><section class="panel"><div class="panel-head"><div><h2>Sales in this period</h2><p>Monthly revenue · SEK</p></div></div><div class="panel-body">${stats.rows.length?chart:'<div class="empty">No sales in this period.</div>'}<p class="legend">Monthly totals use the selected dates; months outside imported coverage have no data.</p></div></section><section class="panel"><div class="panel-head"><div><h2>Popular named products</h2><p>Net sales · explicit product or brand labels</p></div></div><div class="panel-body rank-list">${namedProducts.slice(0,8).map((p,i)=>`<div class="rank-row"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><div class="rank-name">${esc(p.label)}<small>${esc(p.identityNote)}</small><div class="rank-track"><i style="width:${Math.max(0,p.quantity/Math.max(1,namedProducts[0].quantity)*100)}%"></i></div></div><span class="rank-quantity">${fmt(p.quantity)}</span></div>`).join('')||'<p class="muted small">No explicitly named product labels in this period.</p>'}<p class="small muted">Generic beer, cider, soda and cocktail buttons stay in sales history. These totals do not identify stock variants or current inventory.</p></div></section></div>
  <details class="disclosure"><summary>Where these numbers come from</summary><div>${meta?`${fmt(meta.included_rows)} QP transaction lines from the ${dateLabel(meta.range_start)}–${dateLabel(meta.range_end,{year:'numeric'})} export. ${fmt(meta.excluded_rows)} other-chapter lines excluded; ${fmt(meta.unclassified_rows)} uncategorized lines held aside. ${meta.refund_rows} QP refund lines are negative. `:''}Only QP, QP-NPR, QP-VPR, QP-Pitbull and QP-Plåt are included. Generic till buttons do not identify brands or soda variants. Cocktail recipes and mixer consumption are not inferred. This history never deducts inventory automatically. An API adapter can later supply the same daily totals.</div></details>
  <section class="panel history-table"><div class="panel-head"><h2>Monthly totals</h2><span class="muted small">${entries.length} months</span></div><table class="stock-table monthly-table"><thead><tr><th>Month</th><th>Net units</th><th>Revenue · SEK</th></tr></thead><tbody>${entries.map(([month,revenue])=>`<tr><td>${dateLabel(month+'-01',{day:undefined,month:'long',year:'numeric'})}</td><td>${fmt(stats.rows.filter(r=>r.date.startsWith(month)).reduce((s,r)=>s+r.quantity,0))}</td><td>${fmt(revenue/100,2)}</td></tr>`).join('')}</tbody></table></section>${purchaseHistory()}`);
}
function productOptions(value=''){return '<option value="">Choose a product</option>'+CATALOG.map(p=>`<option value="${p.id}" ${p.id===value?'selected':''}>${esc(p.name)} · ${esc(p.requestUnit||p.unit)}</option>`).join('');}
function requestLines(){return requestDraft.lines.map((line,i)=>`<div class="request-line"><div class="field"><label for="product-${i}">Product ${i+1}</label><select id="product-${i}" data-line="${i}" data-key="product_id" required>${productOptions(line.product_id)}</select></div><div class="field"><label for="qty-${i}">Quantity</label><input id="qty-${i}" data-line="${i}" data-key="quantity" type="number" min="1" max="10000" step="1" value="${esc(line.quantity)}" required></div><button type="button" class="remove-line" data-remove="${i}" aria-label="Remove product ${i+1}" ${requestDraft.lines.length===1?'disabled':''}>${icon('x')}</button></div>`).join('');}
function requestsPage(){
  shell(`<div class="page-heading"><div><p class="eyebrow">Bring people together</p><h1>Order requests</h1><p>Tell the barmaster what you need for your event.</p></div>${admin()?'<span class="tag">Barmaster review access</span>':''}</div><div class="request-layout"><section>${submitted?`<div class="success"><h2>${icon('check')} ${api.preview?'Preview request recorded':'Request received'}</h2><p>${api.preview?'This only exists in the local preview.':'Your request is saved and waiting for the barmaster’s review.'} No stock has been reserved yet.</p><p class="small">Reference: ${esc(submitted.slice(0,8).toUpperCase())}</p>${button('Create another request','new-request','primary')}</div>`:`<form id="request-form" class="panel"><div class="form-section"><h2><span class="section-no">01</span>About the event</h2><div class="field-grid"><div class="field full"><label for="event-name">Event name</label><input id="event-name" name="event_name" placeholder="e.g. Autumn gasque" value="${esc(requestDraft.event_name)}" maxlength="120" required></div><div class="field"><label for="event-date">Event date</label><input id="event-date" name="event_date" type="date" value="${esc(requestDraft.event_date)}" min="${today()}" required></div><div class="field"><label for="guests">Expected customers</label><input id="guests" name="guests" type="number" placeholder="e.g. 80" min="1" max="10000" step="1" value="${esc(requestDraft.guests)}" required></div><div class="field full"><label for="requester-name">Your name / organizing team</label><input id="requester-name" name="requester_name" placeholder="Who should the barmaster contact?" value="${esc(requestDraft.requester_name)}" maxlength="100" required></div></div></div><div class="form-section"><h2><span class="section-no">02</span>What do you need?</h2><div id="request-lines">${requestLines()}</div>${button(icon('plus')+' Add another product','add-line','quiet','type="button"')}</div><div class="form-section"><div class="field"><label for="notes">Anything else? <span class="muted">(optional)</span></label><textarea id="notes" name="notes" maxlength="2000" placeholder="Event duration, serving plans, special products or delivery needs…">${esc(requestDraft.notes)}</textarea><small>Special products can be described here for the barmaster to price and source.</small></div><div id="request-error" class="form-error" role="alert"></div><div class="buttons spaced"><button class="btn primary" type="submit">${api.preview?'Try request in preview':'Submit request'}</button><small class="muted">Subject to barmaster approval</small></div></div></form>`}</section><aside class="request-aside"><section id="request-summary" class="request-summary"></section><p class="request-help">A request is a planning conversation. The barmaster checks quantities, availability and delivery timing before approving it. Other members cannot see your contact details or requests.</p></aside></div><section class="panel request-list"><div class="panel-head"><div><h2>${admin()?'Request inbox':'Your requests'}</h2><p>${admin()?'Review event quantities before committing stock.':'Track the barmaster’s response.'}</p></div>${button('Refresh','refresh','compact')}</div>${data.requests.length?data.requests.slice().sort((a,b)=>new Date(b.created_at)-new Date(a.created_at)).map(r=>{const s=requestSummary(r.lines,r.guests);return `<article class="request-card"><div class="request-card-head"><h3>${esc(r.event_name)}</h3>${statusTag(r.status)}</div><p>${dateLabel(r.event_date)} · ${fmt(r.guests)} customers · ${esc(r.requester_name)}</p><ul>${r.lines.map(l=>`<li>${fmt(l.quantity)} ${esc(PRODUCT[l.product_id]?.requestUnit||PRODUCT[l.product_id]?.unit)} ${esc(PRODUCT[l.product_id]?.name)}</li>`).join('')}</ul><p>${fmt(s.perGuest,1)} estimated servings / customer${s.flagged?' · Quantity review recommended':''}</p>${r.notes?`<p>${esc(r.notes)}</p>`:''}${r.review_note?`<p><strong>Barmaster:</strong> ${esc(r.review_note)}</p>`:''}${r.status==='changes_requested'?`<div class="buttons">${button('Revise request','revise-request','compact',`data-id="${r.id}"`)}</div>`:''}${admin()&&['pending','changes_requested'].includes(r.status)?`<div class="buttons">${button('Review request','review-request','primary compact',`data-id="${r.id}"`)}</div>`:''}</article>`;}).join(''):'<div class="empty">No requests yet. New requests will appear here.</div>'}</section>`);
  updateRequestSummary();
}
function updateRequestSummary(){const summary=$('#request-summary');if(!summary)return;const s=requestSummary(requestDraft.lines,requestDraft.guests);summary.innerHTML=`<p class="eyebrow">A quick sense check</p><div class="big">${fmt(s.servings)}</div><h3>estimated servings</h3><div class="ratio"><span>Per customer</span><strong>${requestDraft.guests?fmt(s.perGuest,1):'—'}</strong></div><p>${s.flagged?'More than 4 servings per customer. Add event duration and serving plans so the barmaster can assess the amount.':'Quantities are checked against the number of customers you expect to serve.'}</p><p class="small">One bottle or can = one serving; a 30 L keg ≈ 50 glasses; a sparkling-wine bottle ≈ 6 glasses. This is a planning guide, not a drinking recommendation.</p>`;}
function render(){route=['stock','history','requests'].includes(location.hash.slice(1))?location.hash.slice(1):'stock';if(!data)return;document.title=`QP · ${{stock:'Stock Room',history:'Trends & history',requests:'Order requests'}[route]}`;({stock:stockPage,history:historyPage,requests:requestsPage})[route]();}
async function refresh(){data=await api.loadData();render();}
function authPage(message=''){
  const passwordMode=authMode==='password';
  const fields=passwordMode
    ? '<div class="field"><label for="auth-password">Password</label><input id="auth-password" name="password" type="password" autocomplete="current-password" required></div>'
    : authEmail?'<div class="field"><label for="auth-code">Code from your email</label><input id="auth-code" name="code" autocomplete="one-time-code" inputmode="numeric" pattern="[0-9]{6,8}" required></div><p class="small muted">If your address is invited, you’ll receive a one-time sign-in code.</p>':'';
  $('#app').innerHTML=`<main class="auth-wrap"><section class="auth-card"><div class="brand-mark">QP.</div><p class="eyebrow">Qlubbmästeriet</p><h1>Your stock room.</h1><p>Stock, sales history and event requests, together in one private workspace.</p>${message?`<div class="notice error" role="alert">${esc(message)}</div>`:''}${api.configured?`<form id="auth-form"><div class="field"><label for="auth-email">Email address</label><input id="auth-email" type="email" name="email" autocomplete="username" value="${esc(authEmail)}" required ${!passwordMode&&authEmail?'readonly':''}></div>${fields}<button class="btn primary" type="submit">${passwordMode||authEmail?'Sign in':'Email me a sign-in code'}</button></form>${button(passwordMode?'Use an email code instead':'Use a password instead',passwordMode?'use-email-code':'use-password','quiet','type="button"')}${!passwordMode&&authEmail?button('Use another email','reset-auth','quiet'):''}<p class="small muted spaced">${passwordMode?'Use your Stock Room account. Password sign-in does not send an email.':'Email-code sign-in requires email delivery to be configured.'} Access is limited to approved members.</p>`:'<div class="notice info"><strong>Shared workspace setup is pending.</strong><br>The private database must be connected before members can sign in or submit requests.</div><p class="small muted">No inventory, sales or requests are stored in this public website.</p>'}</section></main>`;
}
const dialog=$('#dialog');
function openDialog(title,content){dialog.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button data-action="close-dialog" aria-label="Close">×</button></div><div class="dialog-body">${content}<div id="dialog-error" class="form-error" role="alert"></div></div>`;if(!dialog.open)dialog.showModal();}
function countDialog(){openDialog('Enter a stock count',`<p>Count what is physically here now. A saved count becomes the new baseline for each product. Leave unknown quantities blank.</p><form id="count-form"><div class="compact-grid">${CATALOG.filter(p=>p.id!=='tap').map(p=>`<label for="count-${p.id}">${esc(p.name)} <span class="muted small">(${esc(p.unit)})</span></label><input class="control" id="count-${p.id}" name="${p.id}" type="number" min="0" ${p.capacity?'max="'+p.capacity+'"':''} step="1" placeholder="—">`).join('')}</div><p class="spaced">Tap beer is counted through the seven keg slots so partial kegs and fridge capacity stay consistent.</p><div class="buttons"><button class="btn primary" type="submit">${api.preview?'Apply preview count':'Save stock count'}</button>${button('Count kegs','kegs','','type="button"')}</div></form>`);}
function movementDialog(kind='delivery'){openDialog(kind==='delivery'?'Confirm a delivery':'Log breakage',`<p>${kind==='delivery'?'Only confirm quantities actually received. This adds stock; a copied supplier order does not.':'Enter broken or discarded items. Quantities are subtracted once.'} Kegs are updated through the keg slots.</p><form id="movement-form" data-kind="${kind}"><div class="field-grid"><div class="field full"><label for="reference">${kind==='delivery'?'Supplier delivery reference':'Breakage reference / reason'}</label><input name="reference" id="reference" maxlength="150" required placeholder="${kind==='delivery'?'e.g. QP-20261006-01':'e.g. Broken Guinness cans, 6 October'}"></div><div class="field full"><label for="occurred">${kind==='delivery'?'Received at':'Occurred at'} · Stockholm time</label><input name="occurred" id="occurred" type="datetime-local" value="${stockholmInput()}" required></div></div><div class="compact-grid spaced">${CATALOG.filter(p=>p.id!=='tap').map(p=>`<label for="move-${p.id}">${esc(p.name)} <span class="muted small">(${esc(p.unit)})</span></label><input class="control" id="move-${p.id}" name="${p.id}" type="number" min="0" max="10000" step="1" placeholder="—">`).join('')}</div><div class="buttons"><button class="btn primary" type="submit">${kind==='delivery'?'Confirm received quantities':'Record breakage'}</button></div></form>`);}
function stockholmInput(value=new Date().toISOString()){const d=new Date(value);return new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Stockholm',year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(d).replace(' ','T');}
// Parse a wall-clock time in Stockholm, independent of the browser's timezone.
function stockholmISO(value){let utc=new Date(value+'Z');for(let i=0;i<3;i++){const displayed=stockholmInput(utc.toISOString());const diff=new Date(value+'Z')-new Date(displayed+'Z');if(!diff)return utc.toISOString();utc=new Date(+utc+diff);}throw Error('That local time does not exist due to the clock change. Choose another time.');}
function kegsDialog(){dialog.close();return openTapRoom({refresh});}
function scheduleDialog(){openDialog('Opening schedule',`<p>Only scheduled openings reduce estimated stock. Skip TENTAP weeks; cancel closed nights. The Google Sheet is not connected to this version.</p>${data.events.slice().sort((a,b)=>new Date(a.starts_at)-new Date(b.starts_at)).map(e=>`<div class="event-row"><div><h3>${esc(e.name)}</h3><p>${dateLabel(e.starts_at,{year:'numeric',hour:'2-digit',minute:'2-digit'})} · ${e.cancelled?'Cancelled':e.multiplier+'× usage'}</p></div>${button('Edit','edit-event','compact',`data-id="${e.id}"`)}</div>`).join('')}<div class="buttons">${button('Add opening','edit-event','primary')}</div>`);}
function eventDialog(id){const e=data.events.find(e=>e.id===id)||{id:crypto.randomUUID(),multiplier:1,kind:'pub'};openDialog('Plan an opening',`<form id="event-form" data-id="${e.id}"><div class="field-grid"><div class="field full"><label for="opening-name">Opening / event name</label><input id="opening-name" name="name" required maxlength="120" value="${esc(e.name)}"></div><div class="field"><label for="opening-at">Starts · Stockholm time</label><input id="opening-at" name="starts_at" type="datetime-local" required value="${e.starts_at?stockholmInput(e.starts_at):''}"></div><div class="field"><label for="opening-kind">Opening type</label><select id="opening-kind" name="kind">${[['pub','Normal pub (usage + extra reservations)'],['event','Event (approved requests only)'],['legacy','Existing estimate (larger of usage or requests)']].map(([v,n])=>`<option value="${v}" ${(e.kind||'legacy')===v?'selected':''}>${n}</option>`).join('')}</select></div><div class="field"><label for="multiplier">Usage multiplier</label><input id="multiplier" name="multiplier" type="number" min="0" max="10" step=".1" value="${e.multiplier}" required><small>Normal 1× · themed pub 1.5×. Event-only openings use approved requests.</small></div><label class="small"><input name="cancelled" type="checkbox" ${e.cancelled?'checked':''}> Cancelled / closed</label></div><div class="buttons"><button class="btn primary" type="submit">Save opening</button></div></form>`);}
function reviewDialog(id){const r=data.requests.find(r=>r.id===id);openDialog('Review '+r.event_name,`<p>${fmt(r.guests)} customers · ${fmt(requestSummary(r.lines,r.guests).perGuest,1)} servings each. Approval is a planning reservation; it does not add or deduct physical stock.</p><form id="review-form" data-id="${r.id}"><div class="field"><label for="review-status">Decision</label><select id="review-status" name="status"><option value="approved">Approve</option><option value="changes_requested">Ask for changes</option><option value="rejected">Decline</option></select></div><div class="field spaced"><label for="review-event">Link to scheduled opening (required to approve)</label><select id="review-event" name="event_id"><option value="">Select an opening on ${dateLabel(r.event_date)}</option>${data.events.filter(e=>!e.cancelled&&localDate(e.starts_at)===r.event_date).map(e=>`<option value="${e.id}">${esc(e.name)}</option>`).join('')}</select><small>Add this event to the opening schedule first. Use a separate Event opening for a separate event, or Normal pub when the request is additional to regular pub service.</small></div><div id="request-impact" class="notice info">${requestImpact(r,'')}</div><div class="field spaced"><label for="review-note">Message to the organizer</label><textarea id="review-note" name="note" maxlength="1000"></textarea></div><div class="buttons"><button class="btn primary" type="submit">Save decision</button></div></form>`);}
function assumptionsDialog(edit=false){openDialog('Planning assumptions',`<p>Rates are the earlier QP estimate per normal opening, not automatically recalculated from this CSV. Soda and Red Bull include mixer use. Variant splits, reserves and alcohol-free pack size need confirmation. No brand-level claims are made from generic sales buttons.</p>${edit?'<form id="settings-form">':''}${CATALOG.map(p=>{const s={...p,...data.settings[p.id]};return `<div class="event-row"><div><h3>${esc(p.name)}</h3><p>${fmt(s.rate,1)} ${esc(p.unit)} / opening · ${s.pack} / pack${p.capacity?' · cap '+p.capacity:''}</p></div>${edit?`<div class="field" style="width:95px"><label for="minimum-${p.id}">Reserve</label><input id="minimum-${p.id}" name="${p.id}" type="number" min="0" max="${p.capacity||1000}" value="${s.minimum}" required></div>`:''}</div>`;}).join('')}${edit?'<div class="buttons"><button class="btn primary" type="submit">Save reserves</button></div></form>':''}`);}
async function save(action,payload,message){await api.write(action,payload);dialog.close();await refresh();toast(api.preview?'Preview updated · not saved or shared':message);}

document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-action],[data-filter],[data-remove]');if(!target||working)return;
  try {
    if(target.dataset.filter){filter=target.dataset.filter;render();return;}
    if(target.dataset.remove!==undefined){requestDraft.lines.splice(Number(target.dataset.remove),1);$('#request-lines').innerHTML=requestLines();updateRequestSummary();return;}
    const action=target.dataset.action;
    if(action==='history-past-month'){range={...pastMonthRange(),category:range.category};render();}
    if(action==='close-dialog')dialog.close();
    if(action==='manage-stock')openDialog('Update the stock room',`<p>Choose what happened. Counts replace the baseline; confirmed deliveries and breakage adjust it.</p><div class="buttons">${button('Enter a count','count','primary')}${button('Receive a delivery','delivery')}${button('Log breakage','breakage')}${button('Kegs & tap gas','kegs')}</div>`);
    if(action==='inventory')await openInventory({refresh,kegs:kegsDialog});
    if(action==='product-library')await openInventory({refresh,kegs:kegsDialog,mode:'manage'});
    if(action==='count'){dialog.close();await openInventory({refresh,kegs:kegsDialog});}
    if(action==='delivery'){dialog.close();await openDeliveries({refresh});}
    if(action==='supplier-order')await openDeliveries({refresh,mode:'order'});
    if(action==='breakage')movementDialog(action);
    if(action==='kegs')kegsDialog();
    if(action==='schedule')scheduleDialog();
    if(action==='edit-event')eventDialog(target.dataset.id);
    if(action==='settings'||action==='assumptions')assumptionsDialog(action==='settings'&&admin());
    if(action==='review-request')reviewDialog(target.dataset.id);
    if(action==='revise-request'){requestDraft={...structuredClone(data.requests.find(r=>r.id===target.dataset.id)),revision:true};submitted=null;render();$('#event-name').focus();window.scrollTo({top:0,behavior:'smooth'});}
    if(action==='add-line'){if(requestDraft.lines.length>=30)throw Error('Maximum 30 products.');requestDraft.lines.push({product_id:'',quantity:1});$('#request-lines').innerHTML=requestLines();$('#product-'+(requestDraft.lines.length-1)).focus();}
    if(action==='new-request'){submitted=null;requestDraft={id:crypto.randomUUID(),lines:[{product_id:'',quantity:1}]};render();}
    if(action==='refresh'){working=true;target.disabled=true;await refresh();toast('Workspace refreshed');}
    if(action==='signout'){data=null;await api.signOut();authEmail='';authPage();}
    if(action==='reset-auth'){authEmail='';authPage();}
    if(action==='use-email-code'||action==='use-password'){authMode=action==='use-password'?'password':'code';authEmail='';authPage();}
    if(action==='copy-order'){
      const list=forecasts(data).filter(p=>p.packs>0);const text='QP · Suggested order\n'+[...new Set(list.map(p=>p.supplier))].map(s=>'\n'+s+'\n'+list.filter(p=>p.supplier===s).map(p=>`${p.name}: ${p.packs} packs (${p.packs*p.pack} ${esc(p.unit)})`).join('\n')).join('\n')+'\n\nCheck counts, pack sizes and supplier delivery timing before placing the order.';
      await navigator.clipboard.writeText(text);toast('Order list copied');
    }
  }catch(error){toast(error.message);}finally{working=false;target.disabled=false;}
});
document.addEventListener('input',event=>{
  if(event.target.id==='pub-purchases-per-customer'){pubPurchasesPerCustomer=event.target.value;$('#pub-customer-scenario').innerHTML=customerScenarioHTML(pubComparison(data,range).groups,pubPurchasesPerCustomer);return;}
  if(!event.target.closest('#request-form'))return;
  const t=event.target;
  if(t.dataset.line!==undefined)requestDraft.lines[Number(t.dataset.line)][t.dataset.key]=t.dataset.key==='quantity'?Number(t.value):t.value;
  else if(t.name)requestDraft[t.name]=t.name==='guests'?Number(t.value):t.value;
  updateRequestSummary();
});
document.addEventListener('submit',async event=>{
  const form=event.target;if(!form.id)return;event.preventDefault();if(working)return;
  const values=Object.fromEntries(new FormData(form)),submit=form.querySelector('[type="submit"]');
  working=true;if(submit)submit.disabled=true;
  try {
    if(form.id==='auth-form'){
      if(authMode==='password'){authEmail=values.email.trim();await api.signInWithPassword(authEmail,values.password);await refresh();}
      else if(!authEmail){await api.sendCode(values.email);authEmail=values.email;authPage();}
      else{await api.verifyCode(authEmail,values.code);await refresh();}
    }
    if(form.id==='history-filter'){
      if(values.from>values.to)throw Error('The start date must be before the end date.');
      if(new Date(values.to)-new Date(values.from)>5*366*86400000)throw Error('Choose a period of five years or less.');
      range=values;render();
    }
    if(form.id==='request-form'){
      const validated=validateRequest(requestDraft);const id=await api.write(requestDraft.revision?'revise_request':'submit_request',validated);submitted=id;requestDraft=validated;await refresh();
    }
    if(form.id==='count-form'){
      const lines=Object.entries(values).filter(([,v])=>v!=='').map(([product_id,q])=>({product_id,quantity:Number(q)}));if(!lines.length)throw Error('Enter at least one quantity.');
      await save('save_count',{id:crypto.randomUUID(),counted_at:new Date().toISOString(),lines},'Stock count saved');
    }
    if(form.id==='movement-form'){
      const kind=form.dataset.kind,lines=CATALOG.filter(p=>p.id!=='tap'&&Number(values[p.id])>0).map(p=>({product_id:p.id,quantity:Number(values[p.id])*(kind==='breakage'?-1:1)}));
      if(!lines.length)throw Error('Enter at least one quantity.');
      const occurred_at=stockholmISO(values.occurred);if(new Date(occurred_at)>new Date())throw Error('Received stock cannot be in the future.');
      await save('record_movement',{id:crypto.randomUUID(),reference:values.reference.trim(),occurred_at,kind,lines},kind==='delivery'?'Delivery recorded':'Breakage recorded');
    }
    if(form.id==='event-form'&&!data.planningAvailable&&values.kind!=='legacy')throw Error('Run supabase/planning.sql in the SQL Editor, then refresh to enable opening types.');
    if(form.id==='event-form')await save('save_event',{id:form.dataset.id,name:values.name.trim(),starts_at:stockholmISO(values.starts_at),multiplier:Number(values.multiplier),kind:values.kind,cancelled:Boolean(values.cancelled)},'Opening saved');
    if(form.id==='settings-form')await save('save_settings',{products:Object.entries(values).map(([id,n])=>({id,minimum:Number(n)}))},'Reserves saved');
    if(form.id==='review-form'){
      if(values.status==='approved'&&!values.event_id)throw Error('Choose the scheduled opening before approving.');
      if(values.status!=='approved'&&!values.note.trim())throw Error('Add a brief reason for the organizer.');
      await save('review_request',{id:form.dataset.id,status:values.status,event_id:values.event_id||null,note:values.note.trim()},'Decision saved');
    }
  }catch(error){
    if(form.id==='auth-form')authPage(error.message);
    else{const box=dialog.open?$('#dialog-error'):$('#request-error');if(box)box.textContent=error.message;else toast(error.message);}
  }finally{working=false;if(submit)submit.disabled=false;}
});
window.addEventListener('hashchange',()=>{render();$('#main')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});});
try {if(api.signedIn())await refresh();else authPage();}catch(error){authPage(error.message);}

// A bounded read tool shares the exact forecast shown on the stock page.
if(document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
  try{await document.modelContext.registerTool({name:'read_stock_forecast',title:'Read QP stock forecast',description:'Read the visible stock forecast for the signed-in organization. Quantities in local preview are samples.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:async input=>{if(!data||!api.signedIn())throw Error('Sign in first.');if(!input||Object.keys(input).length)throw Error('No parameters are accepted.');return {preview:api.preview,products:forecasts(data).map(p=>({product:p.name,quantity:p.quantity,unit:p.unit,normalOpenings:p.coverage,suggestedPacks:p.packs,capacityLimited:p.blocked}))};}},{signal:lifecycle.signal});}catch{ /* Optional enhancement; ordinary controls remain available. */ }
}

document.addEventListener('change',e=>{if(e.target.id==='delivery-choice'){deliveryChoice=e.target.value;render();}if(e.target.id==='review-event'){const r=data.requests.find(r=>r.id===e.target.closest('form').dataset.id);$('#request-impact').innerHTML=requestImpact(r,e.target.value);}});

document.addEventListener('change',event=>{const t=event.target;if(t.id==='pub-year')pubYear=Number(t.value);else if(t.id==='pub-year-metric')pubYearMetric=t.value;else if(t.id==='pub-year-basis')pubYearBasis=t.value;else return;render();$('#'+t.id)?.focus();});

for(const type of ['click','focusin'])document.addEventListener(type,event=>showPubYearPoint(event.target));
document.addEventListener('keydown',event=>{if(['Enter',' '].includes(event.key)&&event.target.matches('[data-year-point]')){event.preventDefault();showPubYearPoint(event.target);}});
